"""Blob storage behind an interface: local filesystem now, S3-compatible later (§5.3)."""

import os
from pathlib import Path
from typing import Protocol
from uuid import uuid4


class BlobStore(Protocol):
    def put(self, key: str, source: Path) -> None: ...
    def path(self, key: str) -> Path: ...
    def delete(self, key: str) -> None: ...
    def exists(self, key: str) -> bool: ...


class LocalBlobStore:
    """Files under a root directory. Keys are generated by the server, never by users."""

    def __init__(self, root: Path) -> None:
        self._root = root.resolve()

    def _resolve(self, key: str) -> Path:
        target = (self._root / key).resolve()
        if not target.is_relative_to(self._root):
            raise ValueError("blob key escapes the storage root")
        return target

    def put(self, key: str, source: Path) -> None:
        target = self._resolve(key)
        target.parent.mkdir(parents=True, exist_ok=True)
        # Unique per write, so two writers of the same key (a recovered worker racing the
        # original) never interleave; the last complete file wins atomically.
        tmp = target.with_name(f"{target.name}.{uuid4().hex}.partial")
        with source.open("rb") as reader, tmp.open("wb") as writer:
            while chunk := reader.read(1 << 20):
                writer.write(chunk)
            writer.flush()
            os.fsync(writer.fileno())
        tmp.replace(target)

    def path(self, key: str) -> Path:
        return self._resolve(key)

    def delete(self, key: str) -> None:
        self._resolve(key).unlink(missing_ok=True)

    def exists(self, key: str) -> bool:
        return self._resolve(key).is_file()
